// MongoDB : exemple minimal avec le pilote officiel Node.js
// npm install mongodb
const { MongoClient } = require('mongodb');

(async () => {
  const client = new MongoClient('mongodb://localhost:27017');
  await client.connect();
  const collection = client.db('demo').collection('messages');
  await collection.insertOne({ texte: 'Hello, World!', creeLe: new Date() });
  const doc = await collection.findOne({ texte: 'Hello, World!' });
  console.log(doc);
  await client.close();
})();

